def priority(task, state, k=0.5, m=2.0, c=1.0, late_boost=1e5, size_pen=0.0, size_ref=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    size_factor = 1.0 / (1.0 + size_pen * task.resource_need / max(size_ref, 1e-6))
    atc = atc * size_factor
    if task.due - state.now < 0:
        return late_boost + atc
    if ratio >= c:
        return 1e6 + atc
    return atc  # tuned (k=0.665,m=7.29,c=0.891,late_boost=2.14e+05,size_pen=0,size_ref=1.49)

def priority(task, state, k=0.5, m=2.0, qthresh=10.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    # under heavy queue, prioritize by tight slack; otherwise ATC-style
    if state.queue_len > qthresh:
        return tier * (-slack)
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))  # tuned (k=0.165,m=6.41,qthresh=5.58)

def priority(task, state, k=0.5, m=2.0, qthresh=4.0, alpha=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wait = state.now - task.release
    if state.queue_len >= qthresh:
        atc += alpha * wait / max(task.estimated_runtime, 1e-6)
    type_bias = 1.0
    if task.task_type == 'reduce':
        type_bias = 1.2
    elif task.task_type == 'join':
        type_bias = 1.1
    return atc * type_bias  # tuned (k=0.127,m=3.24,qthresh=8.72,alpha=0.386)

def priority(task, state, k=1.0, m=2.0, type_boost=1.0, load_w=1.0, q_hi=1.0):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    tb = type_boost if task.task_type == 'reduce' else 1.0
    atc = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    load = state.queue_work / max(state.capacity, 1e-6)
    if load > q_hi:
        return tier * tb * atc * (1.0 + load_w * (load - q_hi))
    return tier * tb * atc  # tuned (k=0.938,m=2.05,type_boost=1.12,load_w=0.322,q_hi=2.88)

def priority(task, state, k=2.0, m=2.5, late_boost=5.0, tight_boost=1.5, tight_ratio=0.5):
    slack = task.due - task.estimated_runtime - state.now
    tier = m if task.tenant == 'premium' else 1.0
    mean_est = max(state.mean_est, 1e-6)
    est = max(task.estimated_runtime, 1e-6)
    # base ATC
    atc = task.weight / est * math.exp(-max(0.0, slack) / (k * mean_est))
    # boost tasks whose runtime estimate is large relative to slack (tight deadline)
    if slack > 0.0 and slack < tight_ratio * est:
        atc *= tight_boost
    # smooth late rescue
    if slack <= 0.0:
        boost = late_boost
    elif slack <= mean_est:
        boost = 1.0 + (late_boost - 1.0) * (1.0 - slack / mean_est)
    else:
        boost = 1.0
    # premium gets extra urgency only when near-late
    if task.tenant == 'premium' and slack <= mean_est:
        tier *= 1.5
    return tier * atc * boost  # tuned (k=3.05,m=2.91,late_boost=11.8,tight_boost=4.14,tight_ratio=0.215)
